WITH valid AS (SELECT *, UPPER(segment) AS segment_upper FROM customers WHERE signup_date > DATE '2023-06-25' AND city IN ('Bangkok', 'London')) SELECT *, RANK() OVER (PARTITION BY segment ORDER BY credit_limit NULLS FIRST) AS credit_limit_rank, AVG(credit_limit) OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS credit_limit_avg_6_prior, FIRST_VALUE(credit_limit) IGNORE NULLS OVER (ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_credit_limit FROM valid
